<?php use App\Helpers\View; ?>
<section class="list-toolbar"><form method="get"><input name="q" value="<?= View::e($search) ?>" placeholder="Search crops"><button class="button secondary">Search</button></form><a class="button primary" href="/crops/create">Add crop</a></section>
<section class="card"><div class="table-wrap"><table><thead><tr><th>Crop ID</th><th>Crop</th><th>Variety</th><th>Category</th><th>Growing days</th><th>Season</th><th>Actions</th></tr></thead><tbody>
<?php foreach($rows as $row):?><tr><td><?=(int)$row['crop_id']?></td><td><?=View::e($row['crop_name'])?></td><td><?=View::e($row['variety'])?></td><td><?=View::e($row['category_name'])?></td><td><?=View::e($row['growing_period_days'])?></td><td><?=View::e($row['season_name'])?></td><td><a href="/crops/edit/<?=(int)$row['crop_id']?>">Edit</a><?php if(($user['role_name']??'')==='Administrator'):?><form method="post" action="/crops/delete/<?=(int)$row['crop_id']?>" class="inline-delete" onsubmit="return confirm('Delete this crop?')"><input type="hidden" name="csrf_token" value="<?=View::e($token)?>"><button>Delete</button></form><?php endif;?></td></tr><?php endforeach;?>
